const a="b15d84c82f7d",e="vertaler + keurder (claude-opus-5-5)",o="2026-10-20",n=[{personId:"B",after:[],nudge:"Zacznij od Bartosza. Był bezpośrednio obok stołu. Znajdź stół i sprawdź, które pola bezpośrednio obok niego są wolne.",reasoning:"Stół stoi na polu rząd 4, kolumna 4. Na lewo od niego, na polu rząd 4, kolumna 3, stoi regał na książki, więc nikt nie może tam być. Bezpośrednio obok stołu zostaje tylko jedno pole.",answer:"Bartosz jest na polu: rząd 3, kolumna 4, tuż powyżej stołu. Na drugim polu bezpośrednio obok stołu stoi regał na książki."},{personId:"A",after:["B"],nudge:"Spójrz na Annę. Była w 2. kolumnie. Które pola w kolumnie 2 są jeszcze możliwe?",reasoning:"Na polu rząd 1, kolumna 2 stoi szafa, a na polu rząd 4, kolumna 2 regał na książki: tam nikt nie może być. W każdym rzędzie jest dokładnie jedna osoba, a rząd 3 zajmuje już Bartosz. W kolumnie 2 zostaje jedno pole.",answer:"Anna jest na polu: rząd 2, kolumna 2. W kolumnie 2 stoją szafa (rząd 1) i regał na książki (rząd 4), a rząd 3 zajmuje Bartosz."},{personId:"C",after:["B","A"],nudge:"Spójrz na Cecylię. Znajdowała się przy oknie. Poszukaj okien na planie.",reasoning:"Okna są przy polach: rząd 1, kolumna 3; rząd 3, kolumna 1; rząd 4, kolumna 4. Na polu rząd 4, kolumna 4 stoi stół, a rząd 3 zajmuje już Bartosz. Które okno zostaje?",answer:"Cecylia jest na polu: rząd 1, kolumna 3, przy oknie u góry. Okno w rzędzie 3 odpada, bo ten rząd zajmuje Bartosz, a przy oknie w rzędzie 4 stoi stół."},{personId:"V",after:["B","A","C"],nudge:"Valentina jest ofiarą i nie ma karty. Zobacz, który rząd i która kolumna są jeszcze puste.",reasoning:"W każdym rzędzie i w każdej kolumnie jest dokładnie jedna osoba. Bartosz, Anna i Cecylia zajmują już rzędy 3, 2 i 1 oraz kolumny 4, 2 i 3. Puste zostają tylko rząd 4 i kolumna 1.",answer:"Valentina jest na polu: rząd 4, kolumna 1. To jedyny rząd i jedyna kolumna, w których jeszcze nikogo nie ma."}],i="Valentina była w piwnicy z winem. Bartosz jest tam jedynym podejrzanym (Anna i Cecylia były w gabinecie), więc to Bartosz jest sprawcą.",r={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},z={source:a,model:e,date:o,steps:n,murderer:i,review:r},l="850dbab4bf0c",d="vertaler + keurder (claude-opus-5-5)",s="2026-10-20",t=[{personId:"C",after:[],nudge:"Zacznij od Cecylii. Była w najniższym rzędzie. Które pola w rzędzie 4 są wolne?",reasoning:"Najniższy rząd to rząd 4. W kolumnach 2, 3 i 4 tego rzędu stoją stoły, więc nikt nie może tam być. Zostaje tylko jedno pole.",answer:"Cecylia jest na polu: rząd 4, kolumna 1. Pozostałe pola w rzędzie 4 zajmują stoły."},{personId:"A",after:["C"],nudge:"Spójrz na Antoniego. Był przy oknie. Poszukaj okien na planie.",reasoning:"Okna są przy polach: rząd 1, kolumna 1; rząd 1, kolumna 3; rząd 4, kolumna 1. W każdej kolumnie jest dokładnie jedna osoba, a kolumnę 1 zajmuje już Cecylia. Które okno zostaje?",answer:"Antoni jest na polu: rząd 1, kolumna 3, przy oknie u góry. Pozostałe okna są w kolumnie 1, a tę kolumnę zajmuje Cecylia."},{personId:"B",after:["C","A"],nudge:"Spójrz na Beatę. Znajdowała się w 2. kolumnie. Które pola w kolumnie 2 są jeszcze możliwe?",reasoning:"Rząd 1 zajmuje Antoni, a rząd 4 Cecylia. Na polu rząd 2, kolumna 2 stoi szafa, więc nikt nie może tam być. W kolumnie 2 zostaje jedno pole.",answer:"Beata jest na polu: rząd 3, kolumna 2. Rzędy 1 i 4 są zajęte, a na polu rząd 2, kolumna 2 stoi szafa."},{personId:"V",after:["C","A","B"],nudge:"Vladimir jest ofiarą i nie ma karty. Zobacz, który rząd i która kolumna są jeszcze puste.",reasoning:"W każdym rzędzie i w każdej kolumnie jest dokładnie jedna osoba. Cecylia, Antoni i Beata zajmują już rzędy 4, 1 i 3 oraz kolumny 1, 3 i 2. Puste zostają tylko rząd 2 i kolumna 4.",answer:"Vladimir jest na polu: rząd 2, kolumna 4. To jedyny rząd i jedyna kolumna, w których jeszcze nikogo nie ma."}],u="Vladimir był w gabinecie. Antoni jest tam jedynym podejrzanym (Beata i Cecylia były w piwnicy z winem), więc to Antoni jest sprawcą.",y={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},m={source:l,model:d,date:s,steps:t,murderer:u,review:y},k="0e590a513929",j="vertaler + keurder (claude-opus-5-5)",w="2026-10-20",p=[{personId:"C",after:[],nudge:"Zacznij od Cypriana. Według jego karty znajdował się na krześle. Poszukaj krzesła na planie.",reasoning:"Cyprian znajdował się na krześle. Jest tylko jedno krzesło, w gabinecie. Tam musi być Cyprian.",answer:"Cyprian jest na polu: rząd 4, kolumna 1. Tam stoi jedyne krzesło, a według jego karty znajdował się na krześle."},{personId:"A",after:["C"],nudge:"Spójrz na Alicję. Była w najwyższym rzędzie. Które pola w rzędzie 1 są jeszcze możliwe?",reasoning:"Na polu rząd 1, kolumna 2 stoi pianino, a na polu rząd 1, kolumna 3 roślina: tam nikt nie może być. W każdej kolumnie jest dokładnie jedna osoba, a kolumnę 1 zajmuje już Cyprian. W rzędzie 1 zostaje jedno pole.",answer:"Alicja jest na polu: rząd 1, kolumna 4. W rzędzie 1 stoją pianino (kolumna 2) i roślina (kolumna 3), a kolumnę 1 zajmuje Cyprian."},{personId:"B",after:["C","A"],nudge:"Spójrz na Bożenę. Była w 2. kolumnie. Które pola w kolumnie 2 są jeszcze możliwe?",reasoning:"W rzędach 1 i 2 kolumny 2 stoi pianino, więc nikt nie może tam być. Rząd 4 zajmuje już Cyprian. W kolumnie 2 zostaje jedno pole.",answer:"Bożena jest na polu: rząd 3, kolumna 2. W górnej części kolumny 2 stoi pianino, a rząd 4 zajmuje Cyprian."},{personId:"V",after:["C","A","B"],nudge:"Valdemar jest ofiarą i nie ma karty. Zobacz, który rząd i która kolumna są jeszcze puste.",reasoning:"W każdym rzędzie i w każdej kolumnie jest dokładnie jedna osoba. Cyprian, Alicja i Bożena zajmują już rzędy 4, 1 i 3 oraz kolumny 1, 4 i 2. Puste zostają tylko rząd 2 i kolumna 3.",answer:"Valdemar jest na polu: rząd 2, kolumna 3. To jedyny rząd i jedyna kolumna, w których jeszcze nikogo nie ma."}],c="Valdemar był w buduarze. Alicja jest tam jedyną podejrzaną (Bożena i Cyprian byli w gabinecie), więc to Alicja jest sprawczynią.",b={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},g={source:k,model:j,date:w,steps:p,murderer:c,review:b},C="f5f4c3de566b",A="vertaler + keurder (claude-opus-5-5)",B="2026-10-20",D=[{personId:"D",after:[],nudge:"Zacznij od Dominika. Jego karta wymienia obiekt. Ile takich obiektów jest na planszy?",reasoning:"Dominik znajdował się na krześle. Spójrz na plan: jest tylko jedno krzesło, w gabinecie. Na którym polu stoi to krzesło?",answer:"Dominik jest na polu: rząd 5, kolumna 2. Stoi tam jedyne krzesło w domu, a jego karta mówi, że znajdował się na krześle."},{personId:"C",after:["D"],nudge:"Spójrz na Cezarego i obie szafy. Które pola są obok szafy i które z nich odpadają z powodu kart Agaty i Bogdana?",reasoning:"Cezary był obok szafy, w tym samym pomieszczeniu. Obok szafy w sypialni leżą pola: rząd 1, kolumna 4; rząd 2, kolumna 5; rząd 3, kolumna 4. Obok szafy w piwnicy z winem leżą pola: rząd 4, kolumna 5 oraz rząd 5, kolumna 4. Kolumna 5 należy do Agaty (skrajna prawa kolumna), rząd 3 do Bogdana, a rząd 5 zajmuje Dominik. Które pole zostaje?",answer:"Cezary jest na polu: rząd 1, kolumna 4. Pozostałe pola obok szafy odpadają: kolumna 5 należy do Agaty, rząd 3 do Bogdana, a rząd 5 zajmuje Dominik."},{personId:"B",after:["D","C"],nudge:"Bogdan znajdował się w 3. rzędzie. Przejdź po polach tego rzędu: które są zablokowane albo odpadają z powodu kolumny?",reasoning:"Bogdan znajdował się w rzędzie 3. Na polu rząd 3, kolumna 3 stoi pianino, więc nikt nie może tam być. Kolumnę 2 zajmuje Dominik, a kolumnę 4 Cezary. Kolumna 5 należy do Agaty, bo była w skrajnej prawej kolumnie. Które pole w rzędzie 3 zostaje?",answer:"Bogdan jest na polu: rząd 3, kolumna 1. W kolumnie 3 stoi pianino, kolumny 2 i 4 zajmują Dominik i Cezary, a kolumna 5 należy do Agaty."},{personId:"V",after:["D","C","B"],nudge:"Teraz ofiara, Valdemar. Które rzędy i kolumny są jeszcze wolne i która kolumna należy już do Agaty?",reasoning:"Rzędy 1, 3 i 5 są zajęte, tak samo jak kolumny 1, 2 i 4. Zostają rzędy 2 i 4 oraz kolumny 3 i 5. Kolumna 5 należy do Agaty, więc Valdemar musi być w kolumnie 3. Na polu rząd 2, kolumna 3 stoi pianino. Gdzie więc może jeszcze leżeć Valdemar?",answer:"Valdemar leży na polu: rząd 4, kolumna 3. Kolumna 5 należy do Agaty, więc Valdemar musi leżeć w kolumnie 3, a na polu rząd 2, kolumna 3 stoi pianino."},{personId:"A",after:["D","C","B","V"],nudge:"Agata jest ostatnią osobą, której nie ma jeszcze na planszy. Co mówi jej karta i który rząd jest jeszcze wolny?",reasoning:"Agata była w skrajnej prawej kolumnie, czyli w kolumnie 5. Rzędy 1, 3, 4 i 5 są już zajęte. Które pole w kolumnie 5 zostaje?",answer:"Agata jest na polu: rząd 2, kolumna 5. Według jej karty była w skrajnej prawej kolumnie, a rzędy 1, 3, 4 i 5 są już zajęte."}],f="Valdemar leży w gabinecie, a Dominik jest jedynym podejrzanym, który też był w gabinecie. Dominik jest więc sprawcą.",E={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},K={source:C,model:A,date:B,steps:D,murderer:f,review:E},V="144a6a6f16d9",h="vertaler + keurder (claude-opus-5-5)",F="2026-10-20",I=[{personId:"B",after:[],nudge:"Zacznij od Borysa w najwyższym rzędzie. Które pola są tam zablokowane i co karta Antoniego mówi o piwnicy z winem?",reasoning:"Borys znajdował się w rzędzie 1. Na polu rząd 1, kolumna 1 stoi szafa, więc nikt nie może tam być. Kolumny 3, 4 i 5 rzędu 1 należą do piwnicy z winem, a Antoni był jedyną osobą w piwnicy z winem. Borysa nie może więc tam być. Które pole w rzędzie 1 zostaje?",answer:"Borys jest na polu: rząd 1, kolumna 2. W kolumnie 1 stoi szafa, a kolumny od 3 do 5 należą do piwnicy z winem, w której był tylko Antoni."},{personId:"D",after:["B"],nudge:"Spójrz na Dorotę i krzesła. Które pola leżą bezpośrednio obok krzesła w tym samym pomieszczeniu, poza piwnicą z winem?",reasoning:"Dorota była bezpośrednio obok krzesła, w tym samym pomieszczeniu. Dwa krzesła stoją w piwnicy z winem, ale tam był tylko Antoni. Pozostałe dwa stoją w oranżerii: na polu rząd 4, kolumna 2 i na polu rząd 5, kolumna 1. Bezpośrednio obok nich leżą pola: kolumna 2, rzędy 3 i 5; rząd 4, kolumna 1. Kolumnę 2 zajmuje Borys. Które pole zostaje?",answer:"Dorota jest na polu: rząd 4, kolumna 1, bezpośrednio obok krzeseł w oranżerii. Piwnica z winem należy do Antoniego, a pola w kolumnie 2 (rzędy 3 i 5) odpadają, bo kolumnę 2 zajmuje Borys."},{personId:"C",after:["B","D"],nudge:"Cecylia była na łóżku. Ile pól zajmuje łóżko i który rząd jest już zajęty?",reasoning:"Jest tylko jedno łóżko, w bibliotece; zajmuje rzędy 3 i 4 w kolumnie 5. Rząd 4 zajmuje Dorota. Na którym polu łóżka może więc jeszcze być Cecylia?",answer:"Cecylia jest na polu: rząd 3, kolumna 5. Łóżko zajmuje rzędy 3 i 4 w kolumnie 5, a rząd 4 zajmuje Dorota."},{personId:"V",after:["B","D","C"],nudge:"Teraz ofiara, Valeria. Które rzędy są jeszcze wolne i w którym z nich musi być Antoni?",reasoning:"Rzędy 1, 3 i 4 są zajęte, więc zostają rzędy 2 i 5. Antoni był w piwnicy z winem, która zajmuje tylko rzędy 1 i 2; rząd 1 należy do Borysa, więc Antoni jest w rzędzie 2. Valeria musi więc leżeć w rzędzie 5. Kolumny 1, 2 i 5 są zajęte, a na polu rząd 5, kolumna 3 stoi stół. Gdzie więc może jeszcze leżeć Valeria?",answer:"Valeria leży na polu: rząd 5, kolumna 4. Rząd 2 należy do Antoniego (piwnica z winem), kolumny 1, 2 i 5 są zajęte, a na polu rząd 5, kolumna 3 stoi stół."},{personId:"A",after:["B","D","C","V"],nudge:"Antoni jest ostatnią osobą, której nie ma jeszcze na planszy. Co mówi jego karta i który rząd i która kolumna są jeszcze wolne?",reasoning:"Antoni był w piwnicy z winem, w rzędzie 1 lub 2. Rząd 1 zajmuje Borys. Kolumnę 4 zajmuje Valeria, a kolumnę 5 Cecylia. Które pole w piwnicy z winem zostaje?",answer:"Antoni jest na polu: rząd 2, kolumna 3, w piwnicy z winem. Rząd 1 zajmuje Borys, kolumnę 4 Valeria, a kolumnę 5 Cecylia."}],$="Valeria leży w bibliotece, a Cecylia jest jedyną podejrzaną, która też była w bibliotece. Cecylia jest więc sprawczynią.",W={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},v={source:V,model:h,date:F,steps:I,murderer:$,review:W},_="dfa59a49f03b",G="vertaler + keurder (claude-opus-5-5)",R="2026-10-20",P=[{personId:"A",after:[],nudge:"Zacznij od Alicji. Znajdź na planie regał na książki i zobacz, które pola obok niego są wolne.",reasoning:"Alicja była obok regału na książki. Jest tylko jeden regał na książki: na polu rząd 5, kolumna 3, w salonie. Na polu rząd 4, kolumna 3 stoi roślina, a pole rząd 5, kolumna 2 leży za ścianą, w holu (i tam też stoi roślina). Które pole obok regału zostaje?",answer:"Alicja jest na polu: rząd 5, kolumna 4, obok regału na książki. Na polu rząd 4, kolumna 3 stoi roślina, a pole rząd 5, kolumna 2 leży za ścianą, w holu."},{personId:"C",after:["A"],nudge:"Teraz Cezary w rzędzie 4. Porównaj jego kartę z kartą Bartosza i spójrz też na Alicję.",reasoning:"Cezary znajdował się w rzędzie 4. Kolumny 1 i 2 rzędu 4 należą do holu, a Bartosz był sam w holu, więc Cezarego nie może tam być. Na polu rząd 4, kolumna 3 stoi roślina, a kolumnę 4 zajmuje Alicja. Które pole w rzędzie 4 zostaje?",answer:"Cezary jest na polu: rząd 4, kolumna 5. Kolumny 1 i 2 rzędu 4 leżą w holu, gdzie Bartosz był sam, w kolumnie 3 stoi roślina, a kolumnę 4 zajmuje Alicja."},{personId:"D",after:["A","C"],nudge:"Spójrz na Dorotę i kolumnę 2. Które pola odpadają z powodu karty Bartosza?",reasoning:"Dorota znajdowała się w kolumnie 2. Rzędy 3, 4 i 5 kolumny 2 należą do holu, gdzie Bartosz był sam; tam Doroty nie może być. Na polu rząd 1, kolumna 2 stoi szafa, więc nikt nie może tam być. Które pole w kolumnie 2 zostaje?",answer:"Dorota jest na polu: rząd 2, kolumna 2. Rzędy od 3 do 5 w kolumnie 2 leżą w holu, gdzie Bartosz był sam, a na polu rząd 1, kolumna 2 stoi szafa."},{personId:"B",after:["A","C","D"],nudge:"Bartosz był w holu. Które rzędy i kolumny holu są jeszcze wolne?",reasoning:"Hol zajmuje rzędy 3, 4 i 5 w kolumnach 1 i 2. Rząd 4 zajmuje Cezary, rząd 5 Alicja, a kolumnę 2 Dorota. Które pole w holu zostaje więc dla Bartosza?",answer:"Bartosz jest na polu: rząd 3, kolumna 1. W holu rząd 4 (Cezary), rząd 5 (Alicja) i kolumna 2 (Dorota) są już zajęte."},{personId:"V",after:["A","C","D","B"],nudge:"Vadim jest ostatnią osobą, której nie ma jeszcze na planszy. Który rząd i która kolumna są jeszcze wolne?",reasoning:"Wszyscy podejrzani są już na swoich miejscach. Rząd 1 to jedyny wolny rząd, a kolumna 3 to jedyna wolna kolumna. Gdzie się przecinają?",answer:"Vadim leży na polu: rząd 1, kolumna 3. Rząd 1 i kolumna 3 to jedyny rząd i jedyna kolumna, w których jeszcze nikogo nie ma."}],N="Vadim leży na korytarzu. Dorota jest jedyną podejrzaną na korytarzu, więc Dorota jest sprawczynią.",Z={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},S={source:_,model:G,date:R,steps:P,murderer:N,review:Z},T="74a91d976380",L="vertaler (claude-opus-5-5)",J="2026-10-20",M=[{personId:"C",after:[],nudge:"Zacznij od Cecylii. Połącz jej kartę z kartą Dawida: która kobieta może być w jego pomieszczeniu? Potem przyjrzyj się pomieszczeniom w górnej połowie planszy.",reasoning:"Cecylia jest jedyną kobietą, więc według karty Dawida Cecylia jest w tym samym pomieszczeniu co Dawid. Cecylia znajdowała się w górnej połowie planszy, ale nie w rzędzie 1: ten rząd należy do Adama (według jego karty był w najwyższym rzędzie). W piwnicy z winem zostaje wtedy tylko rząd 2, w salonie również, bo w rzędzie 3 stoi tam stół. Cecylia i Dawid nie zmieszczą się razem w jednym rzędzie. W sypialni Bartosz, Cecylia i Dawid musieliby się zmieścić razem w rzędach 2 i 3, a to tylko dwa rzędy. Które pomieszczenie zostaje i jakie wolne pole ma ono w górnej połowie planszy?",answer:"Cecylia jest na polu: rząd 3, kolumna 2. Tylko w buduarze Cecylia i Dawid mieszczą się razem, a jedynym wolnym polem buduaru w górnej połowie planszy jest pole z dywanem."},{personId:"A",after:["C"],nudge:"Spójrz na Adama. Jego karta zostawia w najwyższym rzędzie tylko dwa pola. Której kolumny potrzebuje Dawid w buduarze?",reasoning:"Adam był w rzędzie 1 i w lewej połowie planszy. Na polu w kolumnie 2 stoi stół, więc możliwe są tylko kolumny 1 i 3. Dawid jest z Cecylią w buduarze, a buduar ma tylko kolumny 1 i 2. Kolumna 2 należy już do Cecylii, więc Dawid potrzebuje kolumny 1. Które pole zostaje wtedy dla Adama?",answer:"Adam jest na polu: rząd 1, kolumna 3. Kolumna 1 jest potrzebna Dawidowi w buduarze, a w rzędzie 1 w kolumnie 2 stoi stół."},{personId:"E",after:["C","A"],nudge:'Spójrz na Emila i Bartosza. Sypialnia ma tylko dwie kolumny. Co oznacza wtedy dla Emila "gdzieś na prawo od Bartosza" i w którym rzędzie musi być Bartosz?',reasoning:"Bartosz znajdował się w sypialni, czyli w kolumnie 5 lub 6. Emil był gdzieś na prawo od niego, więc Bartosz jest w kolumnie 5, a Emil w kolumnie 6. Rząd 1 należy do Adama, a rząd 3 do Cecylii, więc dla Bartosza zostaje tylko rząd 2. W kolumnie 6 odpadają wtedy dla Emila rzędy 1, 2 i 3, a w rzędach 4 i 5 stoi stół. Gdzie może jeszcze być Emil?",answer:"Emil jest na polu: rząd 6, kolumna 6. Musi być w kolumnie 6; rząd 1 należy do Adama, rząd 2 do Bartosza, rząd 3 do Cecylii, a w rzędach 4 i 5 stoi stół."},{personId:"B",after:["C","A","E"],nudge:"Bartosz znajdował się w sypialni. Skreśl tam rzędy i kolumny, które są już zajęte.",reasoning:"Sypialnia obejmuje rzędy od 1 do 3 w kolumnach 5 i 6. Rząd 1 należy do Adama, rząd 3 do Cecylii, a kolumna 6 do Emila. Które pole zostaje w sypialni?",answer:"Bartosz jest na polu: rząd 2, kolumna 5. W sypialni rząd 1, rząd 3 i kolumna 6 są już zajęte."},{personId:"V",after:["C","A","E","B"],nudge:"Teraz Valdemar. Zobacz, które rzędy i kolumny są jeszcze wolne i której kolumny potrzebuje już Dawid.",reasoning:"Wolne są jeszcze rzędy 4 i 5 oraz kolumny 1 i 4. Dawid jest z Cecylią w buduarze, w kolumnie 1 (kolumna 2 należy do Cecylii). Valdemar musi więc leżeć w kolumnie 4. W rzędzie 5 stoi tam regał na książki. Które pole zostaje?",answer:"Valdemar leży na polu: rząd 4, kolumna 4. Kolumna 1 jest dla Dawida, a w kolumnie 4 w rzędzie 5 stoi regał na książki."},{personId:"D",after:["C","A","E","B","V"],nudge:"Dawid jest ostatni. Który rząd i która kolumna są jeszcze całkiem wolne?",reasoning:"Został już tylko jeden wolny rząd i jedna wolna kolumna. Gdzie się przecinają? Zobacz, czy to pole pasuje do karty Dawida: musi być w tym samym pomieszczeniu co Cecylia.",answer:"Dawid jest na polu: rząd 5, kolumna 1. To jedyny wolny rząd i jedyna wolna kolumna, a pole leży w buduarze, razem z Cecylią."}],O="Valdemar leży w kuchni, a Emil jest jedynym podejrzanym, który tam jest. Emil jest więc sprawcą.",q={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},x={source:T,model:L,date:J,steps:M,murderer:O,review:q},H="a6ef3e81331a",Q="vertaler + keurder (claude-opus-5-5)",U="2026-10-20",X=[{personId:"E",after:[],nudge:"Zacznij od Emila: był przy oknie. Które okna odpadają przez karty Alicji i Cyryla? Potem spójrz na Borysa.",reasoning:"Rząd 1 należy do Alicji, a kolumna 6 do Cyryla, więc ze wszystkich okien zostają tylko okna przy polach w rzędzie 6, w kolumnach 1 i 3: Emil był w rzędzie 6, w holu. Borys był w rogu, a w jego pomieszczeniu był też inny mężczyzna: Cyryl albo Emil. Wszystkie rogi buduaru, w którym był Cyryl, leżą w rzędzie 1, w rzędzie 6 lub w kolumnie 6, a te należą do Alicji, Emila i Cyryla. Borys był więc z Emilem w holu, w rogu poza rzędem 6 i poza kolumną 4 (ta należy do Diany): na polu rząd 5, kolumna 1. Które okno zostaje dla Emila, skoro kolumna 1 należy do Borysa?",answer:"Emil jest na polu: rząd 6, kolumna 3. Rząd 1 należy do Alicji, kolumna 6 do Cyryla, a kolumna 1 do Borysa, więc zostaje tylko okno przy polu rząd 6, kolumna 3."},{personId:"B",after:["E"],nudge:"Borys był w rogu swojego pomieszczenia, a w tym pomieszczeniu był też inny mężczyzna. Kto to może być: Cyryl czy Emil?",reasoning:"Tym drugim mężczyzną jest Cyryl albo Emil. Cyryl był w kolumnie 6, w buduarze; rogi buduaru leżą w rzędzie 1 (należy do Alicji), w rzędzie 6 (zajęty przez Emila) lub w kolumnie 6 (należy do Cyryla). Borys był więc z Emilem w holu. Rogi holu to pola: rząd 5, kolumna 1; rząd 5, kolumna 4; rząd 6, kolumna 1; rząd 6, kolumna 4. Rząd 6 jest zajęty, a kolumna 4 należy do Diany: który róg zostaje?",answer:"Borys jest na polu: rząd 5, kolumna 1. Musiał być z Emilem w holu, a z tamtejszych rogów odpadają te w rzędzie 6 (Emil) i w kolumnie 4 (Diana)."},{personId:"C",after:["E","B"],nudge:"Cyryl był w kolumnie 6 i gdzieś wyżej niż Diana. Najpierw ustal, jak wysoko może być Diana w kolumnie 4.",reasoning:"Diana była w 4. kolumnie. Rząd 1 należy do Alicji, a rzędy 5 i 6 są zajęte, więc zostają dla niej rzędy 2, 3 i 4. Na polu rząd 4, kolumna 4 byłaby obok regału na książki na polu rząd 4, kolumna 3, a tak być nie może. Diana jest więc w rzędzie 2 lub 3. W kolumnie 6 dla Cyryla wolne są jeszcze rzędy 2, 3 i 4, ale musi być gdzieś wyżej niż Diana. Który rząd jeszcze pasuje?",answer:"Cyryl jest na polu: rząd 2, kolumna 6. Diana nie może być niżej niż w rzędzie 3 (pole rząd 4, kolumna 4 leży obok regału na książki), rząd 1 należy do Alicji, a rzędy 5 i 6 są zajęte."},{personId:"D",after:["E","B","C"],nudge:"Diana była w 4. kolumnie. Które rzędy są jeszcze wolne i gdzie stoi regał na książki?",reasoning:"W kolumnie 4 rząd 1 należy do Alicji, a rzędy 2, 5 i 6 zajmują Cyryl, Borys i Emil. Zostają rzędy 3 i 4 w kolumnie 4. Diana nie była obok żadnego regału na książki, a na polu rząd 4, kolumna 3 stoi regał. Które pole zostaje?",answer:"Diana jest na polu: rząd 3, kolumna 4. Rząd 1 należy do Alicji, rzędy 2, 5 i 6 są zajęte, a pole rząd 4, kolumna 4 leży obok regału na książki na polu rząd 4, kolumna 3."},{personId:"V",after:["E","B","C","D"],nudge:"Wolne są jeszcze rzędy 1 i 4 oraz kolumny 2 i 5. Który rząd należy do Alicji?",reasoning:"Rząd 1 należy do Alicji, więc Vera musi leżeć w rzędzie 4. Wolne są tam jeszcze kolumny 2 i 5. Na polu rząd 4, kolumna 2 stoi regał na książki i nikt nie może tam być. Które pole zostaje?",answer:"Vera leży na polu: rząd 4, kolumna 5. Rząd 1 należy do Alicji, a na polu rząd 4, kolumna 2 stoi regał na książki."},{personId:"A",after:["E","B","C","D","V"],nudge:"Została jeszcze jedna osoba. Co mówi karta Alicji?",reasoning:"Alicja znajdowała się w najwyższym rzędzie, czyli w rzędzie 1. Wszystkie kolumny oprócz kolumny 2 są już zajęte. Które to pole?",answer:"Alicja jest na polu: rząd 1, kolumna 2. Znajdowała się w najwyższym rzędzie, a kolumna 2 to jedyna wolna kolumna."}],Y="Cyryl jest sprawcą: jest jedynym podejrzanym w buduarze, gdzie znaleziono Verę.",aa={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ea={source:H,model:Q,date:U,steps:X,murderer:Y,review:aa},oa="eee2a5a776d9",na="vertaler + keurder (claude-opus-5-5)",ia="2026-10-20",ra=[{personId:"B",after:[],nudge:"Zacznij od Bartosza: skrajna prawa kolumna i róg pomieszczenia. Potem spójrz na Eryka, który był w niższym rzędzie niż Bartosz.",reasoning:"Skrajna prawa kolumna należy w całości do oranżerii. Rogi oranżerii w kolumnie 6 leżą w rzędach 1 i 6. Eryk był w niższym rzędzie niż Bartosz. Gdyby Bartosz był w rzędzie 6, najniższym rzędzie, nikt nie mógłby być w niższym rzędzie niż on. Który róg zostaje?",answer:"Bartosz jest na polu: rząd 1, kolumna 6. W kolumnie 6 oranżeria ma rogi w rzędach 1 i 6, a gdyby Bartosz był w rzędzie 6, Eryk nie mógłby być w niższym rzędzie niż on."},{personId:"C",after:["B"],nudge:"Cyprian był w 4. kolumnie. Spójrz na rząd 6: kto może tam jeszcze być? Pomyśl o Eryku i jego łóżku.",reasoning:"Eryk znajdował się na łóżku. Łóżka stoją w kolumnach 3 i 4, ale kolumna 4 należy do Cypriana, więc Eryk jest w kolumnie 3, w rzędzie 3 lub 4. W rzędzie 6 stoją stoły w kolumnach 1 i 2 oraz roślina w kolumnie 5, a kolumna 6 jest zajęta. Kolumna 3 należy do Eryka, który nie może być w rzędzie 6. Kto może więc jeszcze zająć pole w rzędzie 6?",answer:"Cyprian jest na polu: rząd 6, kolumna 4. W rzędzie 6 zostają tylko kolumny 3 i 4; kolumna 3 należy do Eryka na łóżku w rzędzie 3 lub 4, więc rząd 6 jest dla Cypriana."},{personId:"E",after:["B","C"],nudge:"Eryk był na łóżku w kolumnie 3, w rzędzie 3 lub 4. Spójrz na kartę Artura: w którym rogu może on być?",reasoning:"Artur był w rogu swojego pomieszczenia, a w jego pomieszczeniu przebywał też ktoś inny w okularach. Kolumny 3, 4 i 6 oraz rzędy 1 i 6 dla niego odpadają. Zostają wtedy te rogi: rząd 2, kolumna 1 (biblioteka); rząd 3, kolumny 1 i 2 (pokój gościnny). W bibliotece nikt więcej nie zmieściłby się razem z nim, bo rząd 1 jest zajęty, a na polu rząd 2, kolumna 2 stoi regał na książki. Artur jest więc w rzędzie 3. Który rząd dostaje wtedy Eryk?",answer:"Eryk jest na polu: rząd 4, kolumna 3. Musi być na łóżku w kolumnie 3; rząd 3 należy do Artura, który tylko w rogu pokoju gościnnego w rzędzie 3 może mieć przy sobie kogoś w okularach."},{personId:"V",after:["B","C","E"],nudge:"Artur był w rzędzie 3 pokoju gościnnego, razem z kimś innym w okularach. Kto to jest i który rząd i która kolumna zostają dla Vanessy?",reasoning:"Artur był w pokoju gościnnym, w rzędzie 3, jak się okazało wcześniej. Eryk też ma okulary, ale jest w gabinecie. Z Arturem w pokoju gościnnym była więc Danuta. Wolne są jeszcze rzędy 2 i 5; pokój gościnny obejmuje rzędy od 3 do 6, więc Danuta dostaje rząd 5. Artur i Danuta zajmują kolumny 1 i 2. Który rząd i która kolumna zostają dla Vanessy?",answer:"Vanessa leży na polu: rząd 2, kolumna 5. Danuta musi być z Arturem w pokoju gościnnym w rzędzie 5, a oboje zajmują kolumny 1 i 2; dla Vanessy zostają rząd 2 i kolumna 5."},{personId:"D",after:["B","C","E","V"],nudge:"Danuta była w pokoju gościnnym, w rzędzie 5. Co mówi jej karta o Arturze?",reasoning:"Danuta była z Arturem w pokoju gościnnym, w rzędzie 5, jak się okazało wcześniej. Ona i Artur zajmują kolumny 1 i 2. Danuta była gdzieś na lewo od Artura. Która z tych dwóch kolumn leży bardziej na lewo?",answer:"Danuta jest na polu: rząd 5, kolumna 1. Ona i Artur zajmują kolumny 1 i 2, a Danuta była gdzieś na lewo od Artura."},{personId:"A",after:["B","C","E","V","D"],nudge:"Artur jest ostatni. Który rząd i która kolumna są jeszcze wolne?",reasoning:"Wszystkie rzędy oprócz rzędu 3 są zajęte, podobnie jak wszystkie kolumny oprócz kolumny 2. To pole jest rogiem pokoju gościnnego, a Danuta w okularach jest w tym samym pomieszczeniu, czego wymaga karta Artura.",answer:"Artur jest na polu: rząd 3, kolumna 2. To jedyne wolne pole, róg pokoju gościnnego, a Danuta jest w tym samym pomieszczeniu."}],za="Vanessa leży w oranżerii, a Bartosz jest tam jedynym podejrzanym. Bartosz jest więc sprawcą.",la={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},da={source:oa,model:na,date:ia,steps:ra,murderer:za,review:la},sa="fa9cb05db2c4",ta="vertaler (claude-opus-5-5)",ua="2026-10-20",ya=[{personId:"F",after:[],nudge:"Zacznij od Franciszka i Daniela: Daniel był dokładnie dwa rzędy niżej niż Franciszek. W których rzędach może być Daniel, jeśli spojrzysz też na kartę Agaty?",reasoning:"Na polu rząd 1, kolumna 5 stoi regał na książki, więc Franciszek nie jest w rzędzie 1, a Daniel (dokładnie dwa rzędy niżej) jest co najmniej w rzędzie 4. Agata była gdzieś niżej niż Daniel i gdzieś wyżej niż jakiś mężczyzna, więc Agata nie jest w rzędzie 7, a Daniel nie jest ani w rzędzie 6, ani w rzędzie 7. W lewej połowie planszy (kolumny od 1 do 3) w rzędzie 4 stoją tylko regały na książki, więc Daniel jest w rzędzie 5. Franciszek był dokładnie dwa rzędy wyżej: które to pole w kolumnie 5?",answer:"Franciszek jest na polu: rząd 3, kolumna 5. Daniel musi być w rzędzie 5: w rzędzie 4 w lewej połowie planszy stoją tylko regały na książki, a w rzędzie 6 lub 7 Agata nie mogłaby być gdzieś niżej niż on i zarazem gdzieś wyżej niż jakiś mężczyzna."},{personId:"C",after:["F"],nudge:"Cyprian znajdował się w 3. kolumnie. Zobacz, które rzędy należą już do innych: pomyśl o Danielu, Agacie i Eryku.",reasoning:"Daniel jest w rzędzie 5, jak już się okazało. Agata była gdzieś niżej niż Daniel i gdzieś wyżej niż jakiś mężczyzna, więc Agata jest w rzędzie 6. Eryk znajdował się w piwnicy z winem (rzędy 6 i 7), więc Eryk jest w rzędzie 7. W kolumnie 3 w rzędzie 2 stoi stół, w rzędzie 4 regał na książki, a w rzędzie 6 szafa; rząd 3 zajmuje Franciszek. Które pole zostaje dla Cypriana?",answer:"Cyprian jest na polu: rząd 1, kolumna 3. Rząd 3 należy do Franciszka, rząd 5 do Daniela, rząd 6 do Agaty, a rząd 7 do Eryka; w kolumnie 3 w rzędzie 2 stoi stół, w rzędzie 4 regał na książki, a w rzędzie 6 szafa."},{personId:"A",after:["F","C"],nudge:"Agata jest w rzędzie 6. Spójrz na Bożenę: znajdowała się dokładnie jedną kolumnę na lewo od Agaty. Które kolumny są już zajęte?",reasoning:"Agata jest w rzędzie 6, jak już się okazało. Daniel był w lewej połowie planszy, a kolumna 3 należy do Cypriana; ponieważ Eryk był w kolumnie bardziej na lewo niż Daniel, kolumna 2 jest dla Daniela, a kolumna 1 dla Eryka. W rzędzie 6 w kolumnie 3 i w kolumnie 5 stoi po jednej szafie, więc dla Agaty zostają w rzędzie 6 kolumny 4, 6 i 7. Bożena była dokładnie jedną kolumnę na lewo od Agaty, ale kolumna 3 należy do Cypriana, a kolumna 5 do Franciszka. Które pole zostaje wtedy dla Agaty?",answer:"Agata jest na polu: rząd 6, kolumna 7. Kolumny 1 i 2 należą do Eryka i Daniela, w kolumnach 3 i 5 stoi po jednej szafie, a gdyby Agata była w kolumnie 4 lub 6, Bożena musiałaby być w kolumnie 3 (Cyprian) lub 5 (Franciszek)."},{personId:"B",after:["F","C","A"],nudge:"Spójrz na rząd 4. Które pola są tam jeszcze wolne i kto może się tam jeszcze znaleźć?",reasoning:"Bożena była dokładnie jedną kolumnę na lewo od Agaty, więc kolumna 6 jest dla Bożeny. W rzędzie 4 w kolumnach od 1 do 4 stoją regały na książki, kolumnę 5 zajmuje Franciszek, a kolumnę 7 Agata. W rzędzie 4 zostaje tylko jedno pole, a w każdym rzędzie jest dokładnie jedna osoba. Kto musi tam być?",answer:"Bożena jest na polu: rząd 4, kolumna 6. Poza tym w rzędzie 4 są tylko regały na książki oraz kolumny Franciszka i Agaty, a kolumna 6 jest dla Bożeny."},{personId:"E",after:["F","C","A","B"],nudge:"Eryk znajdował się w piwnicy z winem i był w kolumnie bardziej na lewo niż Daniel. Który rząd i która kolumna zostają dla niego?",reasoning:"Piwnica z winem obejmuje rzędy 6 i 7, a rząd 6 zajmuje Agata, więc Eryk jest w rzędzie 7. Daniel był w lewej połowie planszy, a kolumna 3 należy do Cypriana, więc Daniel jest w kolumnie 1 lub 2. Eryk był w kolumnie bardziej na lewo niż Daniel, więc musi być w kolumnie 1. Które to pole?",answer:"Eryk jest na polu: rząd 7, kolumna 1. Rząd 6 należy do Agaty, a Daniel jest w kolumnie 1 lub 2 (kolumna 3 należy do Cypriana), więc w kolumnie bardziej na lewo niż Daniel zostaje dla Eryka tylko kolumna 1."},{personId:"D",after:["F","C","A","B","E"],nudge:"Co mówi karta Daniela? Porównaj ją z miejscem Franciszka.",reasoning:"Daniel był dokładnie dwa rzędy niżej niż Franciszek, więc jest w rzędzie 5. Był w lewej połowie planszy, a tam kolumnę 1 zajmuje Eryk, a kolumnę 3 Cyprian. Które pole zostaje w rzędzie 5?",answer:"Daniel jest na polu: rząd 5, kolumna 2. Był dokładnie dwa rzędy niżej niż Franciszek, a w lewej połowie planszy kolumny 1 (Eryk) i 3 (Cyprian) są już zajęte."},{personId:"V",after:["F","C","A","B","E","D"],nudge:"Wszyscy podejrzani są już na swoich miejscach. Który rząd i która kolumna są jeszcze zupełnie puste?",reasoning:"W każdym rzędzie i w każdej kolumnie jest dokładnie jedna osoba. Rząd 2 i kolumna 4 to jedyny rząd i jedyna kolumna, w których jeszcze nikogo nie ma. Na ich przecięciu stoi kanapa, a na niej można być. Właśnie tam musi więc leżeć Vincent.",answer:"Vincent leży na polu: rząd 2, kolumna 4. To przecięcie jedynego rzędu i jedynej kolumny, które są jeszcze puste."}],ma="Vincent leży w gabinecie. Jedynym podejrzanym w gabinecie jest Franciszek, więc to Franciszek jest sprawcą.",ka={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ja={source:sa,model:ta,date:ua,steps:ya,murderer:ma,review:ka},wa="e42c954df5cd",pa="vertaler + keurder (claude-opus-5-5)",ca="2026-10-20",ba=[{personId:"A",after:[],nudge:"Najpierw ustal rzędy Daniela i Gustawa, a potem spójrz na Beatę i Cecylię. Które rzędy zostają dla Alicji i Feliksa?",reasoning:"Daniel jest w rzędzie 2, a Gustaw w rzędzie 3, więc Beata (górna połowa planszy) musi być w rzędzie 1 lub 4. Cecylia była w wyższym rzędzie niż Beata, więc Beata jest w rzędzie 4, a Cecylia w rzędzie 1. Rzędy od 1 do 4 należą więc do Cecylii, Daniela, Gustawa i Beaty, a Alicja i Feliks muszą być w rzędach od 5 do 8. Tam Alicja może być bezpośrednio obok stołu na polach: rząd 5, kolumny 7 i 8; rząd 6, kolumna 7 (pole rząd 7, kolumna 8 się nie liczy: od stołu oddziela je ściana). Feliks był gdzieś wyżej niż Alicja: w którym rzędzie Alicja więc nie może być?",answer:"Alicja jest na polu: rząd 6, kolumna 7. Rzędy od 1 do 4 należą do Cecylii, Daniela, Gustawa i Beaty; bezpośrednio obok stołu może być w rzędzie 5 lub 6, a w rzędzie 5 Feliks nie mógłby być gdzieś wyżej niż ona."},{personId:"C",after:["A"],nudge:"Cecylia jest w rzędzie 1, jak okazało się przy Alicji. Najpierw ustal, w którym pomieszczeniu jest Beata, a potem przeczytaj kartę Emila.",reasoning:"Beata jest w rzędzie 4 i dzieliła pomieszczenie z co najmniej jedną kobietą. W buduarze to niemożliwe (Cecylia jest w rzędzie 1, Alicja w kuchni), więc Beata jest w kuchni, w kolumnie 4 lub dalej na prawo. Emil był w kolumnie bardziej na prawo niż jakaś kobieta: tą kobietą nie może być Cecylia, bo Emil był gdzieś na lewo od niej, więc jest nią Beata lub Alicja. Emil jest zatem w kolumnie 5 lub dalej, a Cecylia jeszcze dalej na prawo. Na polu rząd 1, kolumna 6 stoi regał na książki, a kolumnę 7 zajmuje Alicja: która kolumna zostaje?",answer:"Cecylia jest na polu: rząd 1, kolumna 8. Emil był w kolumnie bardziej na prawo niż Beata (kuchnia, kolumna 4 lub dalej) albo Alicja, więc jest w kolumnie 5 lub dalej, a Cecylia jeszcze dalej na prawo; na polu rząd 1, kolumna 6 stoi regał na książki, a kolumna 7 jest zajęta."},{personId:"G",after:["A","C"],nudge:"Gustaw był w 3. rzędzie, ale nie był w oranżerii. Które pola w rzędzie 3 wtedy zostają?",reasoning:"Gustaw był w 3. rzędzie i nie był w oranżerii, więc nie jest w kolumnie 1, 2 ani 3. W rzędzie 3 stół zajmuje kolumny 5 i 6, a kolumny 7 i 8 zajmują Alicja i Cecylia. Które pole jest jeszcze wolne?",answer:"Gustaw jest na polu: rząd 3, kolumna 4. W rzędzie 3 pola w kolumnach od 1 do 3 należą do oranżerii, stół zajmuje kolumny 5 i 6, a kolumny 7 i 8 są zajęte."},{personId:"B",after:["A","C","G"],nudge:"Beata jest w kuchni w rzędzie 4. Zobacz, które kolumny są jeszcze wolne, i pomyśl o Emilu.",reasoning:"Beata jest w kuchni w rzędzie 4, jak już się okazało. Kolumny 4 i 8 zajmują Gustaw i Cecylia, a na polu rząd 4, kolumna 7 stoi stół, więc Beata jest w kolumnie 5 lub 6. Emil był w kolumnie 5 lub dalej (jak okazało się przy Cecylii) i gdzieś na lewo od Cecylii, która jest w kolumnie 8; kolumna 7 jest zajęta, więc Emil jest w kolumnie 5 lub 6. Gdyby Beata była w kolumnie 6, Emil musiałby być w kolumnie 5, ale wtedy nie byłby w kolumnie bardziej na prawo niż jakaś kobieta. Którą kolumnę dostaje więc Beata?",answer:"Beata jest na polu: rząd 4, kolumna 5. Musi być w kuchni w kolumnie 5 lub 6, a gdyby była w kolumnie 6, Emil byłby w kolumnie 5 i nie byłby w kolumnie bardziej na prawo niż jakaś kobieta."},{personId:"E",after:["A","C","G","B"],nudge:"Emil musiał być w kolumnie 5 lub 6. Beata jest teraz w kolumnie 5. Które rzędy w kolumnie 6 są jeszcze wolne?",reasoning:"Emil jest w kolumnie 5 lub 6, jak już się okazało, a kolumnę 5 zajmuje Beata. Rzędy 1, 3, 4 i 6 zajmują już Cecylia, Gustaw, Beata i Alicja, a rząd 2 jest dla Daniela. Feliks musiał być w rzędach od 5 do 8 i gdzieś wyżej niż Alicja (rząd 6), więc rząd 5 jest dla Feliksa. Na polu rząd 8, kolumna 6 stoi szafa. Które pole w kolumnie 6 zostaje dla Emila?",answer:"Emil jest na polu: rząd 7, kolumna 6. Musi być w kolumnie 6; rzędy 1, 3, 4 i 6 są zajęte, rząd 2 jest dla Daniela, rząd 5 dla Feliksa (gdzieś wyżej niż Alicja), a na polu rząd 8, kolumna 6 stoi szafa."},{personId:"F",after:["A","C","G","B","E"],nudge:"Feliks jest w rzędzie 5. Przeczytaj drugie zdanie jego karty.",reasoning:"Feliks jest w rzędzie 5, jak już się okazało. Kolumny od 4 do 8 są zajęte, więc wolne są jeszcze kolumny 1, 2 i 3. Feliks znajdował się dokładnie dwie kolumny na prawo od jakiegoś mężczyzny. Gdyby był w kolumnie 1 lub 2, nie byłoby kolumny położonej dokładnie dwie kolumny na lewo od niego. Która kolumna zostaje?",answer:"Feliks jest na polu: rząd 5, kolumna 3. Kolumny od 4 do 8 są zajęte, a gdyby był w kolumnie 1 lub 2, nie mogłoby być żadnego mężczyzny dokładnie dwie kolumny na lewo od niego."},{personId:"V",after:["A","C","G","B","E","F"],nudge:"Gdzie leży Vladimir? Zobacz, które rzędy i kolumny są jeszcze wolne, i pomyśl o karcie Daniela.",reasoning:"Wolne są jeszcze rzędy 2 i 8 oraz kolumny 1 i 2. Daniel był w 2. rzędzie, więc Vladimir leży w rzędzie 8. Na polu rząd 8, kolumna 1 stoi roślina. Na którym polu leży więc Vladimir?",answer:"Vladimir leży na polu: rząd 8, kolumna 2. Rząd 2 jest dla Daniela, a na polu rząd 8, kolumna 1 stoi roślina."},{personId:"D",after:["A","C","G","B","E","F","V"],nudge:"Co mówi karta Daniela?",reasoning:"Daniel był w 2. rzędzie. Która kolumna jest tam jeszcze wolna?",answer:"Daniel jest na polu: rząd 2, kolumna 1. Rząd 2 należy do niego, a kolumna 1 to jedyna wolna kolumna."}],ga="Vladimir leży w buduarze, a Feliks jest jedynym podejrzanym w tym pomieszczeniu: Daniel jest w oranżerii, Cecylia i Gustaw w sypialni, Beata i Alicja w kuchni, a Emil w pokoju gościnnym. To Feliks jest więc sprawcą.",Ca={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},Aa={source:wa,model:pa,date:ca,steps:ba,murderer:ga,review:Ca},Ba="fd37cde9aa3a",Da="vertaler + keurder (claude-opus-5-5)",fa="2026-10-20",Ea=[{personId:"B",after:[],nudge:"Spójrz na kolumny 1 i 2: w jakich pomieszczeniach leżą i kto według swojej karty w ogóle nie może tam być?",reasoning:"Kolumny 1 i 2 leżą w buduarze i w sypialni, a w obu stoi krzesło. W pomieszczeniach Filipa i Dominika nie było żadnego krzesła, więc ich tam nie ma; Dominik był w tym samym pomieszczeniu co Cyntia, więc Cyntii też tam nie ma. Anna była gdzieś na prawo od Cyntii, a Ewa dokładnie cztery kolumny na prawo od Cyntii, więc one też nie mogą tam być. Kolumny 1 i 2 są więc dla Bartosza i Valerii. Bartosz był w 5. rzędzie i nie był obok żadnej kanapy: na polu rząd 5, kolumna 2 byłby obok kanapy, która zajmuje w kolumnie 1 rzędy 4 i 5. Kto jest na samej kanapie, nie jest obok niej. Gdzie jest więc Bartosz?",answer:"Bartosz jest na polu: rząd 5, kolumna 1. Kolumny 1 i 2 są tylko dla Bartosza i Valerii (w obu pomieszczeniach stoi krzesło), a na polu rząd 5, kolumna 2 Bartosz byłby obok kanapy."},{personId:"V",after:["B"],nudge:"Spójrz na rząd 7: ktoś musi tam być. Najpierw zastanów się, w której kolumnie może być Cyntia.",reasoning:"W rzędzie 7 stół zajmuje kolumny 5, 6 i 7, a kolumna 1 jest zajęta. Ewa była dokładnie cztery kolumny na prawo od Cyntii, więc Cyntia jest w kolumnie 1, 2 lub 3, i to w pomieszczeniu bez krzesła (w pomieszczeniu Dominika): to możliwe tylko w kuchni, w kolumnie 3. Dominik też jest w kuchni, a skoro kolumna 3 jest dla Cyntii, kolumna 4 jest dla Dominika. Pola w rzędzie 7 w kolumnach 3 i 4 odpadają więc. Kolumna 2 jest dla Valerii, jak już się okazało. Które pole w rzędzie 7 zostaje?",answer:"Valeria leży na polu: rząd 7, kolumna 2. Ktoś musi być w rzędzie 7: kolumna 1 jest zajęta, w kolumnach od 5 do 7 stoi stół, a kolumny 3 i 4 są dla Cyntii i Dominika w kuchni."},{personId:"E",after:["B","V"],nudge:"Cyntia jest w kolumnie 3. Gdzie jest więc Ewa i który mężczyzna może być dokładnie cztery rzędy niżej niż ona?",reasoning:"Cyntia jest w kolumnie 3, więc Ewa jest dokładnie cztery kolumny na prawo od niej, w kolumnie 7. Ewa znajdowała się dokładnie cztery rzędy wyżej niż jakiś mężczyzna, więc jest w rzędzie 1, 2 lub 3. W rzędzie 7 jest Valeria, kobieta, więc rząd 3 odpada. W rzędzie 6 nie może być żaden mężczyzna: Dominik jest w kuchni, w pomieszczeniu Filipa nie było żadnego krzesła, a w sypialni stoi krzesło. Rząd 2 też więc odpada. Który mężczyzna jest w rzędzie 5?",answer:"Ewa jest na polu: rząd 1, kolumna 7. Musi być w kolumnie 7 (dokładnie cztery kolumny na prawo od Cyntii) i dokładnie cztery rzędy wyżej niż jakiś mężczyzna: to Bartosz w rzędzie 5; w rzędzie 6 nie może być mężczyzny, a w rzędzie 7 jest Valeria."},{personId:"A",after:["B","V","E"],nudge:"Spójrz na kolumnę 6: które pola są tam jeszcze wolne i kto może być w tym pomieszczeniu?",reasoning:"W kolumnie 6 ktoś musi być. W rzędach 2 i 3 stoi tam pianino, w rzędzie 4 szafa, a w rzędzie 7 stół; rzędy 1 i 5 są zajęte. Zostaje tylko pole rząd 6, kolumna 6, w sypialni, gdzie stoi krzesło. Cyntia i Dominik są w kuchni, a w pomieszczeniu Filipa nie było żadnego krzesła. Kto więc musi być na tym polu?",answer:"Anna jest na polu: rząd 6, kolumna 6. To jedyne wolne pole w kolumnie 6 (resztę blokują pianino, szafa i stół), a Cyntia, Dominik i Filip nie mogą być w sypialni, w której stoi krzesło."},{personId:"F",after:["B","V","E","A"],nudge:"Która kolumna zostaje jeszcze dla Filipa? Potem spójrz na kartę Cyntii: dokładnie trzy rzędy niżej niż ona musi być mężczyzna.",reasoning:"Kolumny 3 i 4 są dla Cyntii i Dominika, jak już się okazało, więc Filip jest w kolumnie 5. Tam rzędy 1, 5 i 6 są zajęte, a w rzędzie 7 stoi stół, więc zostają rzędy 2, 3 i 4. Cyntia była dokładnie trzy rzędy wyżej niż jakiś mężczyzna; rząd 1 jest zajęty, a gdyby była w rzędzie 3, dokładnie trzy rzędy niżej byłaby Anna, więc Cyntia jest w rzędzie 2. Dominik jest wtedy w kuchni w rzędzie 3. Który rząd zostaje dla Filipa?",answer:"Filip jest na polu: rząd 4, kolumna 5. Musi być w kolumnie 5; rząd 2 jest dla Cyntii (gdyby była w rzędzie 3, dokładnie trzy rzędy niżej byłaby Anna), a rząd 3 dla Dominika w kuchni."},{personId:"C",after:["B","V","E","A","F"],nudge:"Cyntia jest w kuchni w kolumnie 3. Kto jest dokładnie trzy rzędy niżej niż każdy z rzędów, które są dla niej jeszcze wolne?",reasoning:"Cyntia jest w kuchni w kolumnie 3, więc w rzędzie 1, 2 lub 3. Rząd 1 jest zajęty. Cyntia była dokładnie trzy rzędy wyżej niż jakiś mężczyzna. Dokładnie trzy rzędy niżej niż rząd 3 jest Anna, kobieta. Kto jest dokładnie trzy rzędy niżej niż rząd 2?",answer:"Cyntia jest na polu: rząd 2, kolumna 3. Rząd 1 jest zajęty, a gdyby była w rzędzie 3, dokładnie trzy rzędy niżej byłaby Anna, kobieta; dokładnie trzy rzędy niżej niż rząd 2 jest Bartosz."},{personId:"D",after:["B","V","E","A","F","C"],nudge:"Dominik jest ostatnią osobą, której nie ma jeszcze na planszy. Co mówi jego karta i który rząd oraz która kolumna są jeszcze puste?",reasoning:"Dominik był w tym samym pomieszczeniu co Cyntia, czyli w kuchni. Wszystkie inne osoby są już na planszy, więc musi być w jedynym wolnym rzędzie i w jedynej wolnej kolumnie. Czy to pole leży w kuchni?",answer:"Dominik jest na polu: rząd 3, kolumna 4. To jedyny wolny rząd i jedyna wolna kolumna, a to pole leży w kuchni, razem z Cyntią."}],Ka="Valeria leży w sypialni, a Anna jest jedyną podejrzaną w tym pomieszczeniu. To Anna jest więc sprawczynią.",Va={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},ha={source:Ba,model:Da,date:fa,steps:Ea,murderer:Ka,review:Va},Fa="c895d9aa52fd",Ia="vertaler + keurder (claude-opus-5-5)",$a="2026-10-20",Wa=[{personId:"B",after:[],nudge:"Zacznij od Beaty: który mężczyzna może być dokładnie trzy kolumny na lewo od niej? Potem zobacz, kto może zająć rzędy 1, 2 i 8.",reasoning:"Grzegorz jest w kolumnie 1 (dokładnie dwie kolumny na lewo od Adama w kolumnie 3). Beata była dokładnie trzy kolumny na prawo od jakiegoś mężczyzny: od Adama to kolumna 6 (należy do Cezarego), od Cezarego kolumna 9 (nie istnieje), więc od Grzegorza: kolumna 4. Kto może zająć rząd 1, 2 lub 8? Nie Diana (rząd 4). Nie Adam ani Faustyna: Faustyna znajdowała się dokładnie jeden rząd niżej niż Adam, w dolnej połowie planszy; na polu rząd 4, kolumna 3 stoi regał na książki, a pole rząd 7, kolumna 3 leży poza budynkiem, więc Adam jest w rzędzie 5 lub 6, a Faustyna w rzędzie 6 lub 7. Nie Cezary: w kolumnie 6 rzędy 1 i 2 leżą poza budynkiem, a w rzędzie 8 stoi roślina. Nie Grzegorz: na polu rząd 1, kolumna 1 stoi szafa, rząd 8 leży poza budynkiem, a gdyby był w rzędzie 2, jakiś mężczyzna musiałby być w rzędzie 4, czyli w rzędzie Diany. Te trzy rzędy są więc dla Beaty, Elżbiety i Valentiny. Który z nich jest dla Beaty w kolumnie 4 rogiem?",answer:"Beata jest na polu: rząd 1, kolumna 4, dokładnie trzy kolumny na prawo od Grzegorza. Tylko ona, Elżbieta i Valentina mogą zająć rzędy 1, 2 i 8; pole rząd 2, kolumna 4 nie jest rogiem, a pole rząd 8, kolumna 4 leży poza budynkiem."},{personId:"E",after:["B"],nudge:"Rzędy 1, 2 i 8 są dla Beaty, Elżbiety i Valentiny. Czy Elżbieta może być w najniższym rzędzie, skoro była gdzieś wyżej niż jakiś mężczyzna?",reasoning:"Jak już się okazało przy Beacie, rzędy 1, 2 i 8 są dla Beaty, Elżbiety i Valentiny, a Beata jest w rzędzie 1. Elżbieta była gdzieś wyżej niż jakiś mężczyzna, więc nie w rzędzie 8: jest w rzędzie 2. Kolumna 1 jest dla Grzegorza, kolumna 3 dla Adama, kolumnę 4 zajmuje Beata, a kolumny od 6 do 8 leżą w rzędzie 2 poza budynkiem. Pole rząd 2, kolumna 5 leży w pokoju gościnnym, tak jak Beata, a Elżbieta nie była w tym samym pomieszczeniu co Beata. Które pole zostaje w rzędzie 2?",answer:"Elżbieta jest na polu: rząd 2, kolumna 2. Musiała być w rzędzie 2 (gdzieś wyżej niż jakiś mężczyzna, więc nie w rzędzie 8); kolumna 1 jest dla Grzegorza, kolumna 3 dla Adama, kolumna 4 jest zajęta, kolumna 5 leży w pomieszczeniu Beaty, a kolumny od 6 do 8 poza budynkiem."},{personId:"D",after:["B","E"],nudge:"Diana znajdowała się w 4. rzędzie i była w kolumnie bardziej na lewo niż Cezary. Które kolumny są jeszcze wolne w tym rzędzie?",reasoning:"Diana znajdowała się w 4. rzędzie. Kolumny 2 i 4 zajmują Elżbieta i Beata, kolumna 1 jest dla Grzegorza, a kolumna 6 dla Cezarego. Na polu rząd 4, kolumna 3 stoi regał na książki, a na polu rząd 4, kolumna 8 skrzynia. Pole rząd 4, kolumna 7 odpada, bo Diana była w kolumnie bardziej na lewo niż Cezary w kolumnie 6. Co zostaje?",answer:"Diana jest na polu: rząd 4, kolumna 5. Kolumny 1, 2, 4 i 6 są dla innych, w kolumnie 3 stoi regał na książki, a w kolumnie 8 skrzynia; kolumna 7 nie jest bardziej na lewo niż kolumna Cezarego."},{personId:"V",after:["B","E","D"],nudge:"Który rząd zostaje dla Valentiny? Potem spójrz na kolumny 7 i 8 oraz na Faustynę.",reasoning:"Jak już się okazało przy Beacie, rzędy 1, 2 i 8 były dla Beaty, Elżbiety i Valentiny, więc Valentina jest w rzędzie 8. Kolumny 7 i 8 zostają dla Faustyny i Valentiny, bo Grzegorz, Adam i Cezary mają swoje kolumny. Adam może być w kolumnie 3 tylko w rzędzie 5 lub 6: na polu rząd 4, kolumna 3 stoi regał na książki, pole rząd 7, kolumna 3 leży poza budynkiem, a Faustyna musiała być dokładnie jeden rząd niżej, w dolnej połowie planszy. Faustyna była więc w rzędzie 6 lub 7, a w kolumnie 8 w rzędzie 6 stoi jedna szafa, a w rzędzie 7 druga. Kolumna 7 jest więc dla Faustyny. Które pole w rzędzie 8 zostaje dla Valentiny?",answer:"Valentina leży na polu: rząd 8, kolumna 8. Rząd 8 był dla niej, kolumny od 1 do 4 leżą poza budynkiem, kolumnę 5 zajmuje Diana, na polu rząd 8, kolumna 6 stoi roślina, a kolumna 7 jest dla Faustyny."},{personId:"C",after:["B","E","D","V"],nudge:"Cezary znajdował się w 6. kolumnie, a w jego pomieszczeniu nie było żadnej kobiety. W których pomieszczeniach kolumny 6 jest już kobieta?",reasoning:"W pomieszczeniu Cezarego nie było żadnej kobiety. W kolumnie 6 rzędy 1 i 2 leżą poza budynkiem, a na polu rząd 8, kolumna 6 stoi roślina. Pole rząd 3, kolumna 6 leży w pokoju gościnnym, w którym jest Beata. Pola w rzędach od 4 do 6 kolumny 6 leżą w oranżerii, w której jest Diana. Które pole zostaje?",answer:"Cezary jest na polu: rząd 7, kolumna 6. Rzędy 1 i 2 leżą poza budynkiem, w rzędzie 8 stoi roślina, a w pokoju gościnnym jest Beata, w oranżerii Diana, obie to kobiety."},{personId:"F",after:["B","E","D","V","C"],nudge:"Jak już się okazało przy Valentinie, Faustyna jest w kolumnie 7. Które rzędy dolnej połowy planszy są tam jeszcze wolne?",reasoning:"Jak już się okazało przy Valentinie, kolumna 7 jest dla Faustyny. Wolne są jeszcze rzędy 3, 5 i 6; Faustyna była w dolnej połowie planszy, więc w rzędzie 5 lub 6. W rzędzie 5 Adam musiałby być dokładnie jeden rząd wyżej, w rzędzie 4, ale ten rząd należy do Diany. Gdzie jest Faustyna?",answer:"Faustyna jest na polu: rząd 6, kolumna 7. W kolumnie 7 wolne są tylko rzędy 3, 5 i 6; rząd 3 nie leży w dolnej połowie planszy, a w rzędzie 5 Adam musiałby być w rzędzie 4, który należy do Diany."},{personId:"A",after:["B","E","D","V","C","F"],nudge:"Faustyna jest już na planszy. Co jej karta mówi o Adamie?",reasoning:"Faustyna znajdowała się dokładnie jeden rząd niżej niż Adam, a Faustyna jest w rzędzie 6. Według własnej karty Adam był w 3. kolumnie. Gdzie więc jest?",answer:"Adam jest na polu: rząd 5, kolumna 3. Był w 3. kolumnie, dokładnie jeden rząd wyżej niż Faustyna, która jest w rzędzie 6."},{personId:"G",after:["B","E","D","V","C","F","A"],nudge:"Grzegorz jest ostatnią osobą, której nie ma jeszcze na planszy. Co mówi jego karta?",reasoning:"Rząd 3 i kolumna 1 to jedyny rząd i jedyna kolumna, które są jeszcze wolne. Tam Grzegorz jest dokładnie dwie kolumny na lewo od Adama i dokładnie dwa rzędy wyżej niż on, tak jak mówi jego karta.",answer:"Grzegorz jest na polu: rząd 3, kolumna 1. To ostatni wolny rząd i ostatnia wolna kolumna: dokładnie dwie kolumny na lewo od Adama i dokładnie dwa rzędy wyżej niż on."}],va="Valentina leży w piwnicy z winem. Faustyna była jedyną podejrzaną w piwnicy z winem; Cezary jest w sypialni, Diana w oranżerii, Adam w kuchni, a Beata, Elżbieta i Grzegorz w pokoju gościnnym i w gabinecie. Faustyna jest więc sprawczynią.",_a={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-20"},Ga={source:Fa,model:Ia,date:$a,steps:Wa,murderer:va,review:_a},Ra="e82e6e33b7b4",Pa="vertaler + keurder (claude-opus-5-5)",Na="2026-10-26",Za=[{personId:"A",after:[],nudge:"Zacznij od Agnieszki. Jej karta wspomina najniższy rząd: które pola z tego rzędu leżą w domu?",reasoning:"Agnieszka znajdowała się w najniższym rzędzie, czyli w rzędzie 8. W rzędzie 8 kolumny 1–4 oraz 7–8 leżą poza domem. Roślina stoi na polu: rząd 8, kolumna 6, więc nikt nie może tam być. Które pole w rzędzie 8 zostaje?",answer:"Agnieszka jest na polu: rząd 8, kolumna 5. W rzędzie 8 kolumny 1–4 oraz 7–8 leżą poza domem, a roślina stoi na polu: rząd 8, kolumna 6."},{personId:"V",after:["A"],nudge:"Agnieszka jest w buduarze, a jej karta mówi, że była tam jeszcze jedna kobieta. Która kobieta to może być i gdzie?",reasoning:"Według karty Agnieszki w buduarze była jeszcze jedna kobieta. W buduarze kolumnę 5 zajmuje Agnieszka, a roślina stoi na polu: rząd 8, kolumna 6; wolne jest tylko pole: rząd 7, kolumna 6. Kobiety to Delfina, Ewa i Vilma. Delfina nie była w tym samym pomieszczeniu co Agnieszka, a Ewa znajdowała się w 2. kolumnie. Kto musi więc być na tym wolnym polu?",answer:"Vilma leży na polu: rząd 7, kolumna 6. To jedyne wolne pole w buduarze, a Delfina (nie była w tym samym pomieszczeniu co Agnieszka) i Ewa (była w 2. kolumnie) nie mogą tam być."},{personId:"G",after:["A","V"],nudge:"Spójrz na Gracjana: znajdował się przy oknie. Przejrzyj okna i miej w pamięci Cyryla, Ewę i Filipa.",reasoning:"Cyryl znajdował się dokładnie trzy rzędy wyżej niż Agnieszka, więc rząd 5 jest dla Cyryla; kolumna 2 jest dla Ewy. Pola przy oknie: rząd 1, kolumna 1; rząd 1, kolumna 2; rząd 2, kolumna 8; rząd 5, kolumna 8; rząd 6, kolumna 1 (roślina stoi na polu: rząd 3, kolumna 8, a pole: rząd 8, kolumna 5 zajmuje Agnieszka). Pole: rząd 1, kolumna 2 (Ewa) i pole: rząd 5, kolumna 8 (Cyryl) odpadają. Gracjan był dokładnie jeden rząd wyżej niż Filip, a Filip był w kolumnie bardziej na lewo niż Agnieszka, czyli w jednej z kolumn 1–4. Gdyby Gracjan był na polu: rząd 6, kolumna 1, Filip byłby w rzędzie 7, ale tam jest Vilma. Gdyby Gracjan był na polu: rząd 1, kolumna 1, Filip byłby w rzędzie 2: roślina stoi na polu: rząd 2, kolumna 1, kolumna 2 jest dla Ewy, szafa stoi na polu: rząd 2, kolumna 3, a pole: rząd 2, kolumna 4 jest obok tej szafy (Filip nie był obok żadnej szafy). Które pole przy oknie zostaje?",answer:"Gracjan jest na polu: rząd 2, kolumna 8. Odpadają: pole: rząd 1, kolumna 1 (w rzędzie 2 Filip nie mógłby być w kolumnie bardziej na lewo niż Agnieszka: roślina, kolumna Ewy, szafa, pole obok szafy); pole: rząd 6, kolumna 1 (rząd 7 zajmuje Vilma); pole: rząd 1, kolumna 2 (Ewa) i pole: rząd 5, kolumna 8 (Cyryl)."},{personId:"C",after:["A","V","G"],nudge:"Cyryl znajdował się dokładnie trzy rzędy wyżej niż Agnieszka. Który to rząd i w których kolumnach stoi roślina?",reasoning:"Agnieszka jest w rzędzie 8, więc Cyryl musi być w rzędzie 5. Roślina stoi na polu: rząd 2, kolumna 1, druga na polu: rząd 8, kolumna 6, a trzecia na polu: rząd 3, kolumna 8. Kolumnę 6 zajmuje Vilma, a kolumnę 8 Gracjan. Które pole w rzędzie 5 zostaje?",answer:"Cyryl jest na polu: rząd 5, kolumna 1. Musi być w rzędzie 5 (dokładnie trzy rzędy wyżej niż Agnieszka), a z kolumn z rośliną kolumny 6 (Vilma) i 8 (Gracjan) są już zajęte."},{personId:"F",after:["A","V","G","C"],nudge:"Gracjan był dokładnie jeden rząd wyżej niż Filip, a Filip był w kolumnie bardziej na lewo niż Agnieszka. Który to rząd i które kolumny?",reasoning:"Gracjan jest w rzędzie 2, więc Filip musi być w rzędzie 3. Filip był w kolumnie bardziej na lewo niż Agnieszka, czyli w jednej z kolumn 1–4. Kolumnę 1 zajmuje Cyryl, kolumna 2 jest dla Ewy, a skrzynia stoi na polu: rząd 3, kolumna 3. Które pole zostaje?",answer:"Filip jest na polu: rząd 3, kolumna 4. Musi być w rzędzie 3 (Gracjan był dokładnie jeden rząd wyżej niż Filip) i w kolumnie bardziej na lewo niż Agnieszka; odpadają kolumna 1 (Cyryl), kolumna 2 (Ewa) i kolumna 3 (skrzynia)."},{personId:"E",after:["A","V","G","C","F"],nudge:"Ewa znajdowała się w 2. kolumnie, w pomieszczeniu bez mężczyzn. Które rzędy są jeszcze wolne?",reasoning:"W kolumnie 2 wolne są jeszcze rzędy 1, 4 i 6. Pole: rząd 4, kolumna 2 leży w sypialni, gdzie jest Filip (mężczyzna). Pole: rząd 6, kolumna 2 leży na korytarzu, gdzie jest Cyryl (mężczyzna). Które pole zostaje?",answer:"Ewa jest na polu: rząd 1, kolumna 2. Rząd 4 odpada, bo w sypialni jest Filip, a rząd 6, bo na korytarzu jest Cyryl; w jadalni nie ma mężczyzny."},{personId:"B",after:["A","V","G","C","F","E"],nudge:"Borys był jedynym mężczyzną w swoim pomieszczeniu. Zobacz, które rzędy i kolumny są jeszcze wolne.",reasoning:"Wolne są jeszcze rzędy 4 i 6 oraz kolumny 3 i 7. Pole: rząd 4, kolumna 7 odpada, bo stół zajmuje pola: rząd 4, kolumny 5–7. Pole: rząd 4, kolumna 3 leży w sypialni, gdzie jest Filip, a pole: rząd 6, kolumna 3 na korytarzu, gdzie jest Cyryl; Borys nie byłby tam jedynym mężczyzną. Które pole zostaje?",answer:"Borys jest na polu: rząd 6, kolumna 7. Stół zajmuje pola: rząd 4, kolumny 5–7, a na polach: rząd 4, kolumna 3 (Filip) i rząd 6, kolumna 3 (Cyryl) nie byłby jedynym mężczyzną."},{personId:"D",after:["A","V","G","C","F","E","B"],nudge:"Delfina jest ostatnią osobą, której nie ma jeszcze na planszy. Który rząd i która kolumna są jeszcze wolne?",reasoning:"W każdym rzędzie i w każdej kolumnie jest dokładnie jedna osoba. Rząd 4 i kolumna 3 to ostatnie, w których nikogo nie ma. Pole na ich przecięciu, rząd 4, kolumna 3, leży w sypialni, a nie w buduarze Agnieszki, co zgadza się z kartą Delfiny.",answer:"Delfina jest na polu: rząd 4, kolumna 3. Rząd 4 i kolumna 3 są ostatnie wolne, a to pole leży w sypialni, nie w pomieszczeniu Agnieszki."}],Sa="Vilma leży w buduarze, a tam jedyną podejrzaną jest Agnieszka: to ona jest sprawczynią. Cyryl jest na korytarzu, Filip i Delfina w sypialni, Ewa w jadalni, Gracjan w bibliotece, a Borys w kuchni.",Ta={verdict:"goed",model:"keurder (claude-opus-5-5)",date:"2026-10-26"},La={source:Ra,model:Pa,date:Na,steps:Za,murderer:Sa,review:Ta},Ja=Object.assign({"/.demo/puzzles/i18n/pl/L1-00037ru.json":z,"/.demo/puzzles/i18n/pl/L1-00037sm.json":m,"/.demo/puzzles/i18n/pl/L1-00037ss.json":g,"/.demo/puzzles/i18n/pl/L2-000255s.json":K,"/.demo/puzzles/i18n/pl/L2-000255v.json":v,"/.demo/puzzles/i18n/pl/L2-000256n.json":S,"/.demo/puzzles/i18n/pl/L3-0001qi0.json":x,"/.demo/puzzles/i18n/pl/L3-0002cvm.json":ea,"/.demo/puzzles/i18n/pl/L3-0002cvz.json":da,"/.demo/puzzles/i18n/pl/L4-0002klf.json":ja,"/.demo/puzzles/i18n/pl/L4-0002klr.json":Aa,"/.demo/puzzles/i18n/pl/L4-0002km3.json":ha,"/.demo/puzzles/i18n/pl/L5-0002sbj.json":Ga,"/.demo/puzzles/i18n/pl/L5-005oou4.json":La});export{Ja as default};
